import * as XLSX from 'xlsx';

export const exportToExcel = (projectDetails, sections) => {
    const workbook = XLSX.utils.book_new();

    // Create project details sheet
    const projectSheetData = [
        ['Project Name', projectDetails.projectName],
        ['Client', projectDetails.client],
        ['Contractor', projectDetails.contractor],
        ['Consultant', projectDetails.consultant],
        ['Title', projectDetails.title]
    ];
    const projectSheet = XLSX.utils.aoa_to_sheet(projectSheetData);
    XLSX.utils.book_append_sheet(workbook, projectSheet, 'Project Details');

    // Create sections sheet
    const sectionsSheetData = [['Section Name', 'Subsection Name', 'Document Serial Number', 'Document Name', 'Start Date', 'End Date', 'Status', 'Priority', 'Assigned To', 'Progress']];

    sections.forEach(section => {
        section.subsections.forEach(subsection => {
            subsection.documents.forEach(document => {
                sectionsSheetData.push([
                    section.section_name,
                    subsection.subsection_name,
                    document.serial_number,
                    document.document_name,
                    document.start_date ? document.start_date : 'N/A',
                    document.end_date ? document.end_date : 'N/A',
                    document.status ? document.status : 'N/A',
                    document.priority ? document.priority : 'N/A',
                    document.assigned_to ? document.assigned_to : 'N/A',
                    document.progress !== null ? document.progress : 'N/A'
                ]);
            });
        });
    });

    const sectionsSheet = XLSX.utils.aoa_to_sheet(sectionsSheetData);
    XLSX.utils.book_append_sheet(workbook, sectionsSheet, 'Sections and Documents');

    // Trigger the download
    XLSX.writeFile(workbook, `${projectDetails.projectName}_Details.xlsx`);
};
